package com.cdac.cssip.meeting.service;import com.cdac.cssip.meeting.client.UserServiceClient;import com.cdac.cssip.meeting.dto.MeetingDtos.*;import com.cdac.cssip.meeting.entity.*;import com.cdac.cssip.meeting.repository.*;import com.cdac.cssip.common.enums.Role;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;@Service @RequiredArgsConstructor @Transactional public class MeetingService{private final OnlineMeetingRepository meetings;private final MeetingAttendeeRepository attendees;private final UserServiceClient users;@Value("${internal.api-key}")String key;public MeetingView create(Long staffId,CreateMeetingRequest r){validateStudents(r.studentIds());var m=meetings.save(OnlineMeeting.builder().staffId(staffId).branchId(r.branchId()).title(r.title().trim()).agenda(trim(r.agenda())).platform(r.platform().trim().toUpperCase()).meetingLink(r.meetingLink().trim()).scheduledAt(r.scheduledAt()).durationMinutes(r.durationMinutes()).status("SCHEDULED").build());r.studentIds().stream().distinct().forEach(sid->attendees.save(MeetingAttendee.builder().meetingId(m.getId()).studentId(sid).build()));return view(m);}public MeetingView update(Long staffId,Long id,UpdateMeetingRequest r){var m=owned(staffId,id);editable(m);m.setTitle(r.title().trim());m.setAgenda(trim(r.agenda()));m.setPlatform(r.platform().trim().toUpperCase());m.setMeetingLink(r.meetingLink().trim());m.setScheduledAt(r.scheduledAt());m.setDurationMinutes(r.durationMinutes());return view(meetings.save(m));}public MeetingView cancel(Long staffId,Long id,String reason){var m=owned(staffId,id);editable(m);m.setStatus("CANCELLED");m.setCancellationReason(trim(reason));return view(meetings.save(m));}@Transactional(readOnly=true)public List<MeetingView> staff(Long staffId){return meetings.findByStaffIdOrderByScheduledAtDesc(staffId).stream().map(this::refresh).toList();}@Transactional(readOnly=true)public List<MeetingView> student(Long studentId){return attendees.findByStudentId(studentId).stream().map(a->meetings.findById(a.getMeetingId()).orElseThrow()).map(this::refresh).sorted(Comparator.comparing(MeetingView::scheduledAt)).toList();}private void validateStudents(List<Long> ids){for(Long id:ids){if(users.user(id,key).role()!=Role.STUDENT)throw new IllegalArgumentException("User "+id+" is not STUDENT");}}private OnlineMeeting owned(Long staffId,Long id){var m=meetings.findById(id).orElseThrow(()->new NoSuchElementException("Meeting not found"));if(!m.getStaffId().equals(staffId))throw new SecurityException("You cannot modify another mentor's meeting");return m;}private void editable(OnlineMeeting m){if(!"SCHEDULED".equals(m.getStatus()))throw new IllegalStateException("Only scheduled meetings can be changed");}private MeetingView refresh(OnlineMeeting m){if("SCHEDULED".equals(m.getStatus())&&m.getScheduledAt().plusMinutes(m.getDurationMinutes()).isBefore(LocalDateTime.now())){m.setStatus("COMPLETED");meetings.save(m);}return view(m);}private MeetingView view(OnlineMeeting m){return new MeetingView(m.getId(),m.getStaffId(),m.getBranchId(),m.getTitle(),m.getAgenda(),m.getPlatform(),m.getMeetingLink(),m.getScheduledAt(),m.getDurationMinutes(),m.getStatus(),m.getCancellationReason(),m.getCreatedAt(),attendees.findByMeetingId(m.getId()).stream().map(MeetingAttendee::getStudentId).toList());}private String trim(String s){return s==null||s.isBlank()?null:s.trim();}}
